default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\Logging' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('LogFilePath', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('LogFilePath') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq '$ODV_public_firewall_log_path')) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\Logging [LogFilePath]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\Logging')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\Logging' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\Logging' -Name 'LogFilePath' -Value '$ODV_public_firewall_log_path' -PropertyType String -Force | Out-Null
exit 0
